<template>
  <div class="audit-logs-container">
    <div class="page-header">
      <div class="header-left">
        <el-button class="back-btn" :icon="ArrowLeft" @click="$router.push('/')" circle />
        <h1 class="page-title">系统审计日志</h1>
      </div>
    </div>

    <div class="content-card">
      <div class="card-header">
        <div class="card-title">
          <el-icon class="title-icon"><Document /></el-icon>
          <span>最近 100 条操作记录</span>
        </div>
        <el-button type="primary" plain @click="fetchLogs" :loading="loading" class="refresh-btn">
          <el-icon><Refresh /></el-icon>
          刷新
        </el-button>
      </div>

      <div class="table-wrapper">
        <el-table 
          :data="logs" 
          stripe 
          v-loading="loading"
          class="feishu-table"
          :header-cell-style="{ background: '#fafafa', color: '#606266', fontWeight: '600', fontSize: '14px' }"
          :cell-style="{ fontSize: '14px', color: '#303133' }"
        >
          <el-table-column prop="created_at" label="操作时间" width="180">
            <template #default="{ row }">
              <div class="time-cell">
                <el-icon><Clock /></el-icon>
                <span>{{ formatDate(row.created_at) }}</span>
              </div>
            </template>
          </el-table-column>
          <el-table-column prop="user_name" label="操作人" width="120">
            <template #default="{ row }">
              <div class="user-cell">
                <el-avatar :size="24" src="https://cube.elemecdn.com/0/88/03b0d39583f48206768a7534e55bcpng.png" />
                <span>{{ row.user_name || '未知' }}</span>
              </div>
            </template>
          </el-table-column>
          <el-table-column prop="module" label="模块" width="120">
            <template #default="{ row }">
              <el-tag size="small" class="module-tag">{{ row.module }}</el-tag>
            </template>
          </el-table-column>
          <el-table-column prop="action" label="操作行为" width="150">
            <template #default="{ row }">
              <span class="action-text">{{ row.action }}</span>
            </template>
          </el-table-column>
          <el-table-column prop="content" label="详情">
            <template #default="{ row }">
              <span class="content-text">{{ row.content }}</span>
            </template>
          </el-table-column>
        </el-table>
      </div>

      <div v-if="!loading && logs.length === 0" class="empty-state">
        <el-empty description="暂无日志记录" />
      </div>
    </div>
  </div>
</template>

<script setup>
import { ref, onMounted } from 'vue'
import { ArrowLeft, Document, Refresh, Clock } from '@element-plus/icons-vue'
import api from '@/api'
import dayjs from 'dayjs'
import { ElMessage } from 'element-plus'

const logs = ref([])
const loading = ref(false)

const formatDate = (date) => {
  return dayjs(date).format('YYYY-MM-DD HH:mm:ss')
}

const fetchLogs = async () => {
  loading.value = true
  try {
    const res = await api.getAuditLogs()
    logs.value = res.data.results || res.data || []
  } catch (error) {
    ElMessage.error(api.getErrorMessage(error, '获取日志失败'))
  } finally {
    loading.value = false
  }
}

onMounted(() => {
  fetchLogs()
})
</script>

